<?php get_header(); ?><main id="main" class="wrap page-content"><?php if(is_search()){ ?><h1>Søgeresultater: <?php echo esc_html(get_search_query()); ?></h1><?php }elseif(is_home()){ ?><h1>Nyheder</h1><?php }elseif(is_archive()){the_archive_title('<h1>','</h1>');} ?><div class="post-list"><?php if(have_posts()){while(have_posts()){the_post(); ?><article <?php post_class(); ?>><?php if(is_singular()){the_title('<h1>','</h1>');the_content();wp_link_pages();}else{ ?><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt();} ?></article><?php }the_posts_pagination();}else{ ?><h2>Intet fundet</h2><p>Prøv en anden søgning.</p><?php get_search_form();} ?></div></main><?php get_footer(); ?>